/* Rebindable browser controls; Escape and Enter remain pause/replay shortcuts. */
import {normalizeBindings,normalizeControls,bindingCodes} from './preferences.js';
import {gamepadPreferences} from './gamepad-preferences.js';
const clamp=n=>Math.max(-1,Math.min(1,n));
export class Input{
 constructor(canvas,{active=()=>false,action=()=>{},freeCamera=()=>false,look=()=>{},lookStick=()=>{},bindings,controls,gamepad}={}){
  this.canvas=canvas;this.active=active;this.action=action;this.freeCamera=freeCamera;this.look=look;this.lookStick=lookStick;this.keys=new Set();this.listeners=[];this.padButtons=[];this.controller=false;this.setPreferences({bindings,controls,gamepad});
  const listen=(el,type,fn,options)=>{el.addEventListener(type,fn,options);this.listeners.push([el,type,fn,options]);};
  const edge=code=>{for(const [name,event]of [['camera','camera'],['reset','reset'],['next','next'],['scoreboard','scoreboard'],['quickchat','quickchat'],['chat','chat']])if(this.codes[name].includes(code))this.action(event);};
  listen(window,'keydown',e=>{if(/INPUT|SELECT|TEXTAREA/.test(e.target?.tagName))return;if(e.code==='Escape'){if(this.active())this.action('pause');return;}if(!this.active())return;if(this.used.has(e.code))e.preventDefault();this.keys.add(e.code);if(!e.repeat)edge(e.code);});
  listen(window,'keyup',e=>{this.keys.delete(e.code);if(this.codes.scoreboard.includes(e.code))this.action('hide-scoreboard');});
  const pressMouse=e=>{if(!this.active())return;const code='Mouse'+e.button;if(e.button===1&&!this.used.has(code)&&this.freeCamera()){e.preventDefault();this.dragging=true;this.lastPointer={x:e.clientX,y:e.clientY};try{canvas.setPointerCapture?.(e.pointerId);}catch{}return;}if(this.used.has(code))e.preventDefault();const wasDown=this.keys.has(code);this.keys.add(code);if(!wasDown)edge(code);};listen(canvas,'pointerdown',pressMouse);listen(canvas,'mousedown',pressMouse);
  listen(window,'pointermove',e=>{if(!this.dragging)return;if(!this.active()||!this.freeCamera()){this.dragging=false;return;}const dx=Number.isFinite(e.clientX)&&Number.isFinite(this.lastPointer.x)?e.clientX-this.lastPointer.x:e.movementX||0,dy=Number.isFinite(e.clientY)&&Number.isFinite(this.lastPointer.y)?e.clientY-this.lastPointer.y:e.movementY||0;this.lastPointer={x:e.clientX,y:e.clientY};this.look(-dx*.006,dy*.004);e.preventDefault();});
  const releaseMouse=e=>{if(e.button===1)this.dragging=false;const code='Mouse'+e.button;this.keys.delete(code);if(Number.isInteger(e.buttons))for(const [button,mask]of [[0,1],[1,4],[2,2]])if(!(e.buttons&mask))this.keys.delete('Mouse'+button);if(this.codes.scoreboard.includes(code))this.action('hide-scoreboard');};listen(window,'pointerup',releaseMouse);listen(window,'mouseup',releaseMouse);listen(canvas,'pointercancel',()=>{for(const code of ['Mouse0','Mouse1','Mouse2'])this.keys.delete(code);this.dragging=false;});
  listen(canvas,'contextmenu',e=>e.preventDefault());listen(window,'blur',()=>{this.clear();if(this.active())this.action('pause');});listen(document,'visibilitychange',()=>{if(document.hidden){this.clear();if(this.active())this.action('pause');}});
 }
 setPreferences({bindings=this.bindings,controls=this.controls,gamepad=this.gamepad}={}){this.gamepad=gamepadPreferences(gamepad);this.bindings=normalizeBindings(bindings);this.controls=normalizeControls(controls);this.codes=Object.fromEntries(Object.keys(this.bindings).map(action=>[action,bindingCodes(this.bindings,action)]));this.used=new Set(Object.values(this.codes).flat());this.clear();}
 clear(){this.keys.clear();this.dragging=false;this.blockedButtons=new Set();}
 consumeButtons(ids){for(const id of ids)this.blockedButtons.add(id);}
 read(dt=1/60){
  const pressed=action=>this.codes[action].some(code=>this.keys.has(code)),options=this.controls;
  const result={throttle:+pressed('forward')-+pressed('reverse'),steer:+pressed('left')-+pressed('right'),pitch:+pressed('forward')-+pressed('reverse'),roll:+pressed('rollRight')-+pressed('rollLeft'),jump:pressed('jump'),boost:pressed('boost'),drift:pressed('drift'),dodgeDeadzone:options.dodgeDeadzone};
  try{const pad=Array.from(navigator.getGamepads?.()||[]).find(p=>p?.connected);this.controller=!!pad;if(pad){for(const id of this.blockedButtons)if((pad.buttons[id]?.value||0)<=.5)this.blockedButtons.delete(id);const prefs=this.gamepad,axis=n=>Math.abs(pad.axes[n]||0)>options.deadzone?pad.axes[n]:0,button=action=>this.blockedButtons.has(prefs.buttons[action])?0:pad.buttons[prefs.buttons[action]]?.value||0,drive=button('forward')-button('reverse'),steer=axis(prefs.steerAxis);if(Math.abs(drive)>.05)result.throttle=drive;if(steer)result.steer=steer*(prefs.invertSteering?1:-1);if(axis(prefs.pitchAxis))result.pitch=-axis(prefs.pitchAxis);this.lookStick(this.active()&&this.freeCamera()?axis(prefs.lookX):0,this.active()&&this.freeCamera()?axis(prefs.lookY)*(prefs.invertLookY?-1:1):0);result.roll+=(button('rollRight')>0?1:0)-(button('rollLeft')>0?1:0);result.jump||=button('jump')>.5;result.boost||=button('boost')>.5;result.drift||=button('drift')>.5;for(const name of ['camera','pause','scoreboard','reset','next','quickchat','chat']){const id=prefs.buttons[name],down=button(name)>.5;if(down&&!this.padButtons[id]&&this.active())this.action(name);if(!down&&this.padButtons[id]&&name==='scoreboard')this.action('hide-scoreboard');this.padButtons[id]=down;}}else{this.padButtons=[];this.lookStick(0,0);}}catch{this.controller=false;this.lookStick(0,0);}
  if(!this.active())return {...result,throttle:0,steer:0,pitch:0,roll:0,jump:false,boost:false,drift:false};
  result.steer=clamp(result.steer*options.steeringSensitivity);result.pitch=clamp(result.pitch*options.aerialSensitivity*(options.invertPitch?-1:1));result.roll=clamp(result.roll*options.aerialSensitivity);return result;
 }
 dispose(){this.listeners.forEach(([el,type,fn,options])=>el.removeEventListener(type,fn,options));this.clear();}
}
